#pragma once

#include "lxp-theme.h"

/*
 * Themes can bundle installable data under <theme dir>/data/, laid out
 * like $XDG_DATA_HOME (data/themes/X/openbox-3/themerc,
 * data/lxqt/themes/X/...). Only these kinds are installable: themes,
 * lxqt/themes and icons — never e.g. dbus-1/services, which would run
 * programs. Each installable directory contains a ".lxp-asset" marker:
 *
 *   empty            generated by lxqt-personalizer: replaces a previous
 *                    copy, but never a directory without the marker
 *   install=if-missing  third-party theme bundled in a pack: installed
 *                    only when nothing of that name exists yet
 */

#define LXP_ASSET_MARKER     ".lxp-asset"
#define LXP_ASSET_IF_MISSING "install=if-missing\n"

gboolean lxp_assets_install(const LxpTheme *theme, GError **error);

/*
 * <theme dir>/data/<kind>/<name> if it exists and contains <probe>
 * (may be NULL), else NULL. Lets previews use assets before installing.
 */
char    *lxp_assets_find(const LxpTheme *theme, const char *kind, const char *name,
                         const char *probe);

/* Is <relpath> (e.g. "themes/Foo") an installable unit location? */
gboolean lxp_assets_kind_allowed(const char *relpath);
